using System;using System.IO;using System.Linq;
static class LauncherTests {static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string local=Path.Combine(root,"Jago-Workscape.exe"),external=Path.Combine(root,"Elsewhere.exe");File.WriteAllText(local,"fixture");var plan=SuitePreviewLauncher.Plan(root,new[]{"workscape","library","pulse"},null);if(plan.Count!=1||plan[0].Item1!=local||plan[0].Item2!="")throw new Exception("Installing Workscape preloads other apps");File.Delete(local);File.WriteAllText(external,"fixture");plan=SuitePreviewLauncher.Plan(root,new[]{"library","pulse"},external);if(plan.Count!=1||plan[0].Item1!=external)throw new Exception("Existing Workscape not preferred");plan=SuitePreviewLauncher.Plan(root,new[]{"library","pulse","unknown","library"},null);if(plan.Count!=2||plan.Any(p=>p.Item2!=""))throw new Exception("No-Workscape app selection is wrong");plan=SuitePreviewLauncher.Plan(root,new[]{"workscape","library"},null);if(plan.Count!=1||plan[0].Item1!=local)throw new Exception("Missing selected Workscape must be repaired before launching other apps");Console.WriteLine("PASS: Workscape only, existing Workscape preference, optional selected apps and missing-app repair routing");}}
